// The committed artifact module (ADR 0004): the text written from a built .wasm, and the .wasm read back from it.
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";

export const ARTIFACT_PATH = fileURLToPath(new URL("../src/mldsa87-wasm.ts", import.meta.url));

/** @param {Uint8Array} wasm */
export function artifactModule(wasm) {
  const bytes = Buffer.from(wasm);
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  return [
    "// Generated by scripts/generate-artifact.mjs through `pnpm build:wasm`. Do not edit.",
    `// The module is ${bytes.length} bytes with SHA-256 ${sha256}.`,
    // Typed as string so that tsc doesn't repeat the literal in the declaration file.
    `export const MLDSA87_WASM_BASE64: string = "${bytes.toString("base64")}";`,
    "",
  ].join("\n");
}

/** @param {string} text */
export function wasmOfArtifact(text) {
  const base64 = /^export const MLDSA87_WASM_BASE64: string = "([A-Za-z0-9+/]*={0,2})";$/m.exec(text)?.[1];
  if (base64 === undefined) {
    throw new Error("the artifact module holds no MLDSA87_WASM_BASE64 literal");
  }
  return new Uint8Array(Buffer.from(base64, "base64"));
}
